/bin/bash -lc "curl -s -m5 http://localhost:8080/api/v1/openapi.json | python3 -c \"
import json,sys
spec=json.load(sys.stdin)
for p,ops in spec['paths'].items():
    if 'cart' in p.lower():
        for m,o in ops.items():
            print(m.upper(), p)
            print('  params:', [ (x['name'], x.get('schema',{}).get('type','')) for x in o.get('parameters',[]) ])
\""

